export interface Course {
  id: string;
  name: string;
  /** Town / region shown on reveal. */
  place: string;
  country: string;
  lat: number;
  lon: number;
  /** Hint shown while guessing. Should not name the town. */
  clue: string;
  /** 1 = famous, 2 = known to golf fans, 3 = deep cut. Easier holes are played first. */
  tier: 1 | 2 | 3;
}

